package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	n := readInt(in)
	m := readInt(in)

	arr := make([]int, n)
	required := 0
	for i := 0; i < n; i++ {
		arr[i] = readInt(in)
		required += arr[i]
	}

	typeDays := make(map[int][]int)
	for i := 0; i < m; i++ {
		d := readInt(in)
		typ := readInt(in)
		if typ >= 1 && typ <= n && arr[typ-1] > 0 {
			typeDays[typ] = append(typeDays[typ], d)
		}
	}

	for typ := range typeDays {
		sort.Ints(typeDays[typ])
	}

	lo := required
	hi := 2 * required
	valid := hi

	for lo <= hi {
		mid := (lo + hi) / 2
		if isEnough(mid, required, arr, typeDays) {
			valid = mid
			hi = mid - 1
		} else {
			lo = mid + 1
		}
	}

	fmt.Fprintln(out, valid)
}

func isEnough(day, required int, arr []int, typeDays map[int][]int) bool {
	totalCoin := day
	req := required

	ddays := make([]int, day+1)

	for typ, days := range typeDays {
		idx := sort.Search(len(days), func(i int) bool { return days[i] > day })
		if idx > 0 {
			lastDay := days[idx-1]
			if lastDay <= day {
				ddays[lastDay] += arr[typ-1]
			}
		}
	}

	removed := 0
	for i := 1; i <= day; i++ {
		coins := i - removed
		toRemove := coins
		if ddays[i] < toRemove {
			toRemove = ddays[i]
		}
		removed += toRemove
		totalCoin -= toRemove
		req -= toRemove
	}

	return req*2 <= totalCoin
}

func readInt(in *bufio.Reader) int {
	var b byte
	var err error

	for {
		b, err = in.ReadByte()
		if err != nil {
			return 0
		}
		if b >= '0' && b <= '9' || b == '-' {
			break
		}
	}

	neg := false
	if b == '-' {
		neg = true
		b, _ = in.ReadByte()
	}

	n := 0
	for b >= '0' && b <= '9' {
		n = n*10 + int(b-'0')
		b, err = in.ReadByte()
		if err != nil {
			break
		}
	}

	if neg {
		return -n
	}
	return n
}

