package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var (
	in  *FastScanner
	out *FastWriter
)

type FastScanner struct {
	reader *bufio.Reader
	buf    []byte
	idx    int
	size   int
}

func NewFastScanner() *FastScanner {
	return &FastScanner{
		reader: bufio.NewReader(os.Stdin),
		buf:    make([]byte, 1024*1024),
	}
}

func (fs *FastScanner) readByte() byte {
	if fs.idx >= fs.size {
		fs.size, _ = fs.reader.Read(fs.buf)
		fs.idx = 0
		if fs.size == 0 {
			return 0
		}
	}
	b := fs.buf[fs.idx]
	fs.idx++
	return b
}

func (fs *FastScanner) skipSpace() {
	for {
		b := fs.readByte()
		if b == 0 || (b > ' ') {
			fs.idx--
			break
		}
	}
}

func (fs *FastScanner) NextInt() int {
	fs.skipSpace()
	b := fs.readByte()
	neg := false
	if b == '-' {
		neg = true
		b = fs.readByte()
	}
	x := 0
	for b >= '0' && b <= '9' {
		x = x*10 + int(b-'0')
		b = fs.readByte()
	}
	if neg {
		return -x
	}
	return x
}

func (fs *FastScanner) NextIntArray(n int) []int {
	arr := make([]int, n)
	for i := 0; i < n; i++ {
		arr[i] = fs.NextInt()
	}
	return arr
}

type FastWriter struct {
	writer *bufio.Writer
	buf    []byte
	idx    int
}

func NewFastWriter() *FastWriter {
	return &FastWriter{
		writer: bufio.NewWriter(os.Stdout),
		buf:    make([]byte, 1024*1024),
	}
}

func (fw *FastWriter) flush() {
	if fw.idx > 0 {
		fw.writer.Write(fw.buf[:fw.idx])
		fw.idx = 0
	}
}

func (fw *FastWriter) writeByte(b byte) {
	if fw.idx == len(fw.buf) {
		fw.flush()
	}
	fw.buf[fw.idx] = b
	fw.idx++
}

func (fw *FastWriter) WriteString(s string) {
	for i := 0; i < len(s); i++ {
		fw.writeByte(s[i])
	}
}

func (fw *FastWriter) Println(args ...interface{}) {
	fmt.Fprintln(fw.writer, args...)
}

func (fw *FastWriter) Printf(format string, args ...interface{}) {
	fmt.Fprintf(fw.writer, format, args...)
}

func (fw *FastWriter) Close() {
	fw.flush()
	fw.writer.Flush()
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func sum(arr []int) int {
	s := 0
	for _, v := range arr {
		s += v
	}
	return s
}

func isEnough(day, required int, arr []int, typeDays map[int][]int) bool {
	totalCoin := day
	req := required

	ddays := make([]int, day+1)
	for typ, days := range typeDays {
		// find floor(day) in days (sorted ascending)
		// idx = first index where days[idx] > day
		idx := sort.Search(len(days), func(i int) bool { return days[i] > day })
		if idx == 0 {
			continue // all days > day
		}
		lastDay := days[idx-1]
		ddays[lastDay] += arr[typ-1]
	}

	removed := 0
	for i := 1; i <= day; i++ {
		coins := i - removed
		toRemove := min(coins, ddays[i])
		removed += toRemove
		totalCoin -= toRemove
		req -= toRemove
	}

	return req*2 <= totalCoin
}

func solve() {
	n := in.NextInt()
	m := in.NextInt()
	arr := in.NextIntArray(n)
	required := sum(arr)

	typeDays := make(map[int][]int)
	for i := 0; i < m; i++ {
		d := in.NextInt()
		typ := in.NextInt()
		if arr[typ-1] <= 0 {
			continue
		}
		typeDays[typ] = append(typeDays[typ], d)
	}

	// sort days for each type
	for _, days := range typeDays {
		sort.Ints(days)
	}

	lo := required
	hi := 2 * required
	valid := hi
	for lo <= hi {
		mid := (lo + hi) / 2
		if isEnough(mid, required, arr, typeDays) {
			valid = mid
			hi = mid - 1
		} else {
			lo = mid + 1
		}
	}
	out.Println(valid)
}

func main() {
	in = NewFastScanner()
	out = NewFastWriter()
	defer out.Close()

	solve()
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"sort"
)

var (
	in  *FastScanner
	out *FastWriter
)

type FastScanner struct {
	scanner *bufio.Scanner
}

func NewFastScanner() *FastScanner {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
