		d := in.IntNext()
		typ := in.IntNext()
		if s.arr[typ-1] <= 0 {
			continue
		}
		s.typeDays[typ] = append(s.typeDays[typ], d)
	}

	// Sort days for each type to allow binary search (floor)
	for typ := range s.typeDays {
		sort.Ints(s.typeDays[typ])
	}

	lo := s.required
	hi := 2 * s.required
	valid := hi

	for lo <= hi {
		mid := (lo + hi) / 2
		if s.isEnough(mid) {
