}

func (s *Solver) isEnough(day int) bool {
	totalCoin := day
	req := s.required

	// ddays[i] = total items available for purchase on day i (last sale day <= day)
	ddays := make([]int, day+1)

	for typ, days := range s.typeDays {
		// Find largest day <= 'day' (floor)
		// sort.Search returns first index where days[idx] > day
		idx := sort.Search(len(days), func(i int) bool { return days[i] > day })
		if idx == 0 {
			continue // no sale day <= day
		}
		lastDay := days[idx-1]
		ddays[lastDay] += s.arr[typ-1]
	}

	removed := 0
	for i := 1; i <= day; i++ {
		coins := i - removed
		toRemove := minInt(coins, ddays[i])
		removed += toRemove
		totalCoin -= toRemove
		req -= toRemove
	}

	return req*2 <= totalCoin
}

